const jobData = $('Receive Job Data').first().json;
const llmResponse = $input.first().json;

try {
  // Check for API error
  if (llmResponse.error) {
    throw new Error(llmResponse.error.message || 'Claude API error');
  }

  // Extract content from Claude response
  const content = llmResponse.content?.[0]?.text || '';

  // Find JSON in the response (might be wrapped in markdown code blocks)
  let jsonStr = content;
  const jsonMatch = content.match(/```json\n?([\s\S]*?)\n?```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1];
  }

  const courseData = JSON.parse(jsonStr);

  // Build course object for API
  const course = {
    ...courseData,
    instructor_id: jobData.body.instructor_id,
    guild_id: jobData.body.guild_id,
    price_credits: jobData.body.price_credits || 0,
    is_free: jobData.body.is_free !== false,
    language: jobData.body.language || 'fr',
    thumbnail_url: jobData.body.thumbnail_url || null,
    status: 'draft'
  };

  return {
    json: {
      success: true,
      course: course,
      job_id: jobData.job_id,
      discord_channel_id: jobData.body.discord_channel_id,
      user_id: jobData.body.user_id,
      bot_token: jobData.body.bot_token
    }
  };
} catch (e) {
  return {
    json: {
      success: false,
      error: e.message,
      job_id: jobData.job_id,
      discord_channel_id: jobData.body.discord_channel_id,
      user_id: jobData.body.user_id,
      bot_token: jobData.body.bot_token
    }
  };
}
